use verus::prelude::*;

#[verifier::decreases(s.len())]
#[verifier::requires(true)]
#[verifier::ensures(result.len() == s.len())]
#[verifier::ensures(
    forall(|i: usize| i < s.len() ==>
        result[i] == if s[i] == old { new } else { s[i] }
))]
fn replace_chars(s: &[char], old: char, new: char) -> Vec<char> {
    s.iter()
     .map(|&c| if c == old { new } else { c })
     .collect()
}

fn main() {
    let input = vec!['a', 'b', 'a', 'c'];
    let result = replace_chars(&input, 'a', 'x');
    assert_eq!(result, vec!['x', 'b', 'x', 'c']);

    let empty: Vec<char> = Vec::new();
    let result_empty = replace_chars(&empty, 'z', 'y');
    assert!(result_empty.is_empty());
}